import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'

import { addProductIntent } from 'lib/utils/product-intents'

import { ProductIntentContext, ProductKey } from '~/queries/schema/schema-general'

import { onboardingEventUsageLogic } from '../onboardingEventUsageLogic'
import { SELF_DRIVING_INTENT_METADATA, resolveSetup } from '../shared/useCases'
import type { OnboardingUseCaseKey } from '../shared/useCases'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface useCaseSelectionLogicValues {
    extraTools: ProductKey[]
    selectedUseCase: OnboardingUseCaseKey | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface useCaseSelectionLogicActions {
    reportSelfDrivingOnboardingGoalSelected: (goal: string) => {
        goal: string
    } // onboardingEventUsageLogic
    addExtraTools: (tools: ProductKey[]) => {
        tools: ProductKey[]
    }
    selectUseCase: (useCase: OnboardingUseCaseKey) => {
        useCase: OnboardingUseCaseKey
    }
}

export type useCaseSelectionLogicType = MakeLogicType<useCaseSelectionLogicValues, useCaseSelectionLogicActions>

/** Holds the use case declared on the onboarding's use-case step; the rest of the flow spins off it. */
export const useCaseSelectionLogic = kea<useCaseSelectionLogicType>([
    path(['scenes', 'onboarding', 'self-driving', 'useCaseSelectionLogic']),

    connect(() => ({
        actions: [onboardingEventUsageLogic, ['reportSelfDrivingOnboardingGoalSelected']],
    })),

    actions({
        selectUseCase: (useCase: OnboardingUseCaseKey) => ({ useCase }),
        addExtraTools: (tools: ProductKey[]) => ({ tools }),
    }),

    reducers({
        selectedUseCase: [
            null as OnboardingUseCaseKey | null,
            // Persisted so a refresh (or the GitHub OAuth round-trip on the install step) keeps
            // the use-case-conditional steps in the flow.
            { persist: true },
            {
                selectUseCase: (_, { useCase }) => useCase,
            },
        ],
        extraTools: [
            [] as ProductKey[],
            { persist: true },
            {
                addExtraTools: (state, { tools }) => Array.from(new Set([...state, ...tools])),
            },
        ],
    }),

    listeners(({ actions }) => ({
        selectUseCase: ({ useCase }) => {
            actions.reportSelfDrivingOnboardingGoalSelected(useCase)
            void addProductIntent({
                product_type: resolveSetup(useCase).primaryProduct,
                intent_context: ProductIntentContext.ONBOARDING_PRODUCT_SELECTED_PRIMARY,
                metadata: SELF_DRIVING_INTENT_METADATA,
            })
        },
    })),
])
